Repair the complete CommonJS source below. Export exactly `{ validateRecord }`. `schema` must be a plain object whose values are `{ type, required }`, where `type` is `string`, `number`, or `boolean` and `required` is Boolean; malformed schemas throw `TypeError`. For a non-null, non-array object value, validate schema keys in lexicographic order, ignore extra value keys, and return `{ valid, errors }`. Missing required fields add `"KEY is required"`; missing optional fields add nothing. Present fields of the wrong type add `"KEY must be TYPE"`; numbers must also be finite. A malformed value, including `null` or an array, returns `{ valid: false, errors: ['value must be an object'] }`. Do not mutate or alias either argument. Return a corrected complete source file.

```javascript
'use strict';

function validateRecord(value, schema) {
  if (!schema || typeof schema !== 'object' || Array.isArray(schema)) throw new TypeError('invalid schema');
  for (const rule of Object.values(schema)) {
    if (!rule || typeof rule !== 'object' || !['string', 'number', 'boolean'].includes(rule.type) || typeof rule.required !== 'boolean') throw new TypeError('invalid rule');
  }
  if (typeof value !== 'object' || Array.isArray(value)) {
    return { valid: false, errors: ['value must be an object'] };
  }

  const errors = [];
  for (const key of Object.keys(schema).sort()) {
    const rule = schema[key];
    const present = Object.prototype.hasOwnProperty.call(value, key);
    if (!present) {
      if (rule.required) errors.push(key + ' is required');
      continue;
    }
    const candidate = value[key];
    if (typeof candidate !== rule.type || (rule.type === 'number' && !Number.isFinite(candidate))) {
      errors.push(key + ' must be ' + rule.type);
    }
  }
  return { valid: errors.length === 0, errors };
}

module.exports = { validateRecord };
```

