'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['validateRecord']);
const { validateRecord } = api;

const schema = {
  zeta: { type: 'boolean', required: true },
  age: { type: 'number', required: true },
  name: { type: 'string', required: false }
};
assert.deepEqual(validateRecord({ age: 42, zeta: false, extra: 'ignored' }, schema), {
  valid: true, errors: []
});
assert.deepEqual(validateRecord({}, schema), {
  valid: false, errors: ['age is required', 'zeta is required']
});
assert.deepEqual(validateRecord({ age: '42', name: 7, zeta: 'false' }, schema), {
  valid: false,
  errors: ['age must be number', 'name must be string', 'zeta must be boolean']
});
assert.deepEqual(validateRecord({ age: Infinity, zeta: true }, schema), {
  valid: false, errors: ['age must be number']
});
assert.deepEqual(validateRecord({ age: NaN, zeta: true }, schema), {
  valid: false, errors: ['age must be number']
});
assert.deepEqual(validateRecord(null, schema), {
  valid: false, errors: ['value must be an object']
});
assert.deepEqual(validateRecord([], schema), {
  valid: false, errors: ['value must be an object']
});
assert.deepEqual(validateRecord('value', schema), {
  valid: false, errors: ['value must be an object']
});

const value = { age: 1, zeta: true };
const result = validateRecord(value, schema);
result.errors.push('mutated');
assert.deepEqual(value, { age: 1, zeta: true });
assert.deepEqual(schema.age, { type: 'number', required: true });
assert.deepEqual(validateRecord(value, schema), { valid: true, errors: [] });
assert.deepEqual(validateRecord({}, {}), { valid: true, errors: [] });

for (const badSchema of [
  null,
  [],
  { x: null },
  { x: [] },
  { x: { type: 'date', required: true } },
  { x: { type: 'string', required: 1 } }
]) assert.throws(() => validateRecord({}, badSchema), TypeError);

